private int getMaxAPIAvailable(String dir) {
  File d = new File(dir);
  if (!d.exists()) {
      throw new RuntimeException("The Android platform directory you have specified (" + dir + ") does not exist. Please check.");
  }
  try {
      File[] files = d.listFiles();
      if (files == null) return -1;

      int maxApi = -1;
      for (File f : files) {
          try {
              String name = f.getName();
              if (f.isDirectory() && name.startsWith("android-")) {
                  String[] parts = name.split("android-");
                  if (parts.length < 2) continue;

                  int v = Integer.decode(parts[1]);
                  if (v > maxApi) maxApi = v;
              }
          } catch (SecurityException e) {
              // 忽略无权限访问的文件
          }
      }
      return maxApi;
  } catch (SecurityException e) {
      throw new RuntimeException("No permission to access directory: " + dir, e);
  }
}
